//! Parity tests for the scalar dtype helpers (`tests/fixtures/dtypes.json`, generated by
//! `tests/fixtures/gen_dtypes.py`).

mod common;

use common::{cases, compare_values, decode, encode, load_fixture};
use meerschaum_kernel::cast;
use meerschaum_kernel::dtypes::{self, Srid};
use meerschaum_kernel::serialize;
use meerschaum_kernel::value::Value;
use serde_json::{Value as J, json};

fn srid_json(s: &Srid) -> J {
    match s {
        Srid::Code(i) => json!(i),
        Srid::Authority(s) => json!(s),
    }
}

fn check_value(case: &J, result: Result<Value, String>, failures: &mut Vec<String>) {
    match (case.get("ok"), result) {
        (Some(expected), Ok(actual)) => {
            if let Err(m) = compare_values(expected, &encode(&actual)) {
                failures.push(format!("{case}: {m}"));
            }
        }
        (None, Err(_)) => {}
        (Some(_), Err(e)) => failures.push(format!("{case}: unexpected error {e}")),
        (None, Ok(v)) => failures.push(format!("{case}: expected error, got {}", encode(&v))),
    }
}

#[test]
fn dtypes_parity() {
    let fixture = load_fixture("dtypes");
    let mut failures = Vec::new();
    let mut counts = std::collections::BTreeMap::<String, usize>::new();
    for case in cases(&fixture) {
        let f = case["fn"].as_str().unwrap();
        *counts.entry(f.to_string()).or_default() += 1;
        let args = case["args"].as_array().unwrap();
        let s = |i: usize| args[i].as_str().unwrap_or("");
        match f {
            "to_pandas_dtype" => {
                let got = dtypes::to_pandas_dtype(s(0));
                if J::String(got.clone()) != case["ok"] {
                    failures.push(format!("{case}: got {got}"));
                }
            }
            "are_dtypes_equal" => {
                let got = dtypes::are_dtypes_equal(s(0), s(1));
                if J::Bool(got) != case["ok"] {
                    failures.push(format!("{case}: got {got}"));
                }
            }
            "are_dtypes_equal_dict" => {
                let to_pairs = |j: &J| -> Vec<(String, String)> {
                    j.as_object()
                        .unwrap()
                        .iter()
                        .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                        .collect()
                };
                let l = to_pairs(&args[0]);
                let r = to_pairs(&args[1]);
                let got = dtypes::are_dtypes_maps_equal(
                    l.iter().map(|(a, b)| (a.as_str(), b.as_str())),
                    r.iter().map(|(a, b)| (a.as_str(), b.as_str())),
                );
                if J::Bool(got) != case["ok"] {
                    failures.push(format!("{case}: got {got}"));
                }
            }
            "is_dtype_numeric" => {
                if J::Bool(dtypes::is_dtype_numeric(s(0))) != case["ok"] {
                    failures.push(format!("{case}"));
                }
            }
            "is_dtype_special" => {
                if J::Bool(dtypes::is_dtype_special(s(0))) != case["ok"] {
                    failures.push(format!("{case}"));
                }
            }
            "get_geometry_type_srid" | "get_geometry_type_srid_4326" => {
                let default = if f.ends_with("4326") {
                    Srid::Code(4326)
                } else {
                    Srid::Code(0)
                };
                let got = dtypes::get_geometry_type_srid(s(0), "geometry", default);
                match (got, case.get("ok")) {
                    (Ok((t, srid)), Some(ok)) => {
                        if json!([t, srid_json(&srid)]) != *ok {
                            failures.push(format!("{case}: got ({t}, {srid})"));
                        }
                    }
                    (Err(_), None) => {}
                    (got, _) => failures.push(format!("{case}: got {got:?}")),
                }
            }
            "get_numeric_precision_scale" => {
                let got = dtypes::get_numeric_precision_scale(args[0].as_str());
                if json!([got.0, got.1]) != case["ok"] {
                    failures.push(format!("{case}: got {got:?}"));
                }
            }
            "value_is_null" => {
                let got = cast::value_is_null(&decode(&args[0]));
                if J::Bool(got) != case["ok"] {
                    failures.push(format!("{case}: got {got}"));
                }
            }
            "none_if_null" => check_value(
                case,
                Ok(cast::none_if_null(&decode(&args[0]))),
                &mut failures,
            ),
            "attempt_cast_to_numeric" => check_value(
                case,
                cast::attempt_cast_to_numeric(&decode(&args[0]), false, None, None),
                &mut failures,
            ),
            "attempt_cast_to_numeric_q" => check_value(
                case,
                cast::attempt_cast_to_numeric(
                    &decode(&args[0]),
                    args[1].as_bool().unwrap(),
                    args[2].as_i64(),
                    args[3].as_i64(),
                ),
                &mut failures,
            ),
            "attempt_cast_to_uuid" => check_value(
                case,
                Ok(cast::attempt_cast_to_uuid(&decode(&args[0]))),
                &mut failures,
            ),
            "attempt_cast_to_bytes" => check_value(
                case,
                Ok(cast::attempt_cast_to_bytes(&decode(&args[0]))),
                &mut failures,
            ),
            "serialize_decimal" | "serialize_decimal_q" => {
                let v = decode(&args[0]);
                let result = match &v {
                    Value::Decimal(d) => {
                        let (q, p, sc) = if f == "serialize_decimal_q" {
                            (true, args[1].as_i64(), args[2].as_i64())
                        } else {
                            (false, None, None)
                        };
                        serialize::serialize_decimal(d, q, p, sc)
                            .map(|o| o.map(Value::Str).unwrap_or(Value::Null))
                            .map_err(|e| e.to_string())
                    }
                    other => Ok(other.clone()),
                };
                check_value(case, result, &mut failures);
            }
            "quantize_decimal" => {
                let Value::Decimal(d) = decode(&args[0]) else {
                    panic!()
                };
                let result = d
                    .quantize(args[1].as_i64().unwrap(), args[2].as_i64().unwrap())
                    .map(Value::Decimal)
                    .map_err(|e| e.to_string());
                check_value(case, result, &mut failures);
            }
            "coerce_timezone" | "coerce_timezone_strip" => check_value(
                case,
                cast::coerce_timezone(&decode(&args[0]), f.ends_with("strip"))
                    .map_err(|e| e.to_string()),
                &mut failures,
            ),
            "to_datetime_py" | "to_datetime_py_nocoerce" => check_value(
                case,
                cast::to_datetime(&decode(&args[0]), f == "to_datetime_py", None)
                    .map_err(|e| e.to_string()),
                &mut failures,
            ),
            "datetime_to_int" => check_value(
                case,
                cast::datetime_to_int(&decode(&args[0]), s(1))
                    .map(Value::Int)
                    .map_err(|e| e.to_string()),
                &mut failures,
            ),
            "round_time" => {
                let Value::Datetime(dt) = decode(&args[0]) else {
                    panic!()
                };
                let delta = args[1].as_f64().map(|f| f as i64).unwrap_or(60_000_000);
                let got = cast::round_time(&dt, delta, cast::RoundTo::parse(s(2)));
                check_value(case, Ok(Value::Datetime(got)), &mut failures);
            }
            "get_next_precision_unit" => {
                let got = dtypes::get_next_precision_unit(s(0), args[1].as_bool().unwrap());
                match (got, case.get("ok")) {
                    (Ok(u), Some(ok)) if J::String(u.into()) == *ok => {}
                    (Err(_), None) => {}
                    (got, _) => failures.push(format!("{case}: got {got:?}")),
                }
            }
            other => panic!("unhandled fixture function {other}"),
        }
    }
    assert!(
        counts.values().sum::<usize>() > 5000,
        "fixture too small: {counts:?}"
    );
    if !failures.is_empty() {
        panic!(
            "{} dtype parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
